"""The title eval set is FROZEN (ADR-034, decision 3): generated by S43, reviewed by the user
(two rounds), then fixed. These tests fail on any edit — regenerating it is a deliberate, recorded act
(new hashes here and in ADR-034), never a side effect. They also re-check the properties the split
relies on.

Hashes are over the content with line endings normalized to LF, so a git checkout that converts
line endings does not look like an edit.
"""

from __future__ import annotations

import hashlib
from pathlib import Path

import pytest
import yaml

_PROMPTS = Path(__file__).resolve().parents[2] / "prompts"
# sha256 of the LF-normalized file, recorded when the set was frozen (2026-09-26). The files were
# written on Windows with CRLF; their raw sha256 (as S43 printed it) is ca61b6199a5d… (grounding) and
# 95bff347edf3… (end-to-end) — ADR-034 records both.
FROZEN = {
    "eval-titles-grounding.yaml": "5c9d23899306f2b773d3ecd4aa1146681fe0c091eba682f74eaddb5cec145eb5",
    "eval-titles.yaml": "eaec71fa61c48001103b14a260f43055e57cfee103c5fdfcb95d9a5d0a96f3c0",
}


def _items(name: str) -> list[dict]:
    return yaml.safe_load((_PROMPTS / name).read_text(encoding="utf-8"))["examples"]


@pytest.mark.parametrize("name", sorted(FROZEN))
def test_title_eval_set_is_frozen(name: str) -> None:
    content = (_PROMPTS / name).read_bytes().replace(b"\r\n", b"\n")
    assert hashlib.sha256(content).hexdigest() == FROZEN[name], (
        f"{name} changed after it was frozen — tuning on a moving test set invalidates the dev/test "
        "split (decision 3). If the change is deliberate, record the new hash here and in ADR-034."
    )


def test_ids_unique_and_splits_valid() -> None:
    for name in FROZEN:
        items = _items(name)
        assert len({i["id"] for i in items}) == len(items), name
        assert {i["split"] for i in items} == {"dev", "test"}, name


def test_no_title_family_on_both_sides() -> None:
    """The split is by title family: every family (both families of a two-title item) is on one side."""
    side: dict[str, str] = {}
    for name in FROZEN:
        for item in _items(name):
            for fam in item.get("families", [item["family"]]):
                assert side.setdefault(fam, item["split"]) == item["split"], (name, item["id"], fam)
